(406084, 35690, 327, '<td valign="top">Hey teachers! leave us kids alone. :) Nice shot, love their attitude!</td>', 'Hey teachers! leave us kids alone. :) Nice shot, love their attitude!', '2003-09-01 11:11:25.000000', NULL, 1),
(406085, 35890, 327, '<td valign="top">Very good shot....wow this is nice. Love the pose, light and colors. Good work.</td>', 'Very good shot....wow this is nice. Love the pose, light and colors. Good work.', '2003-09-01 11:12:11.000000', NULL, 1),
