(406250, 35805, 7969, '<td valign="top">Technically well done, little lacking in ''wow'' but certainly meets the challenge.</td>', 'Technically well done, little lacking in ''wow'' but certainly meets the challenge.', '2003-09-01 13:10:18.000000', NULL, 1),
(406251, 35777, 7969, '<td valign="top">Good thought use a teacher in the challenge, without them our schools would certainly be significantly less.</td>', 'Good thought use a teacher in the challenge, without them our schools would certainly be significantly less.', '2003-09-01 13:11:35.000000', NULL, 1),
