(406897, 35865, 10084, '<td valign="top">Great composition. Colors are good ,both in the buses and the sky. The angle that you captured is nice. It leads your eyes down the rolls of buses. Not only is this a great back to school shot, it is a great repetition shot. Beautiful.</td>', 'Great composition. Colors are good ,both in the buses and the sky. The angle that you captured is nice. It leads your eyes down the rolls of buses. Not only is this a great back to school shot, it is a great repetition shot. Beautiful.', '2003-09-02 05:39:28.000000', NULL, 1),
(406898, 35646, 10084, '<td valign="top">Good composition.The clouds are really beautiful. Love the angle, this is the level that kids would look up at the sky. Wonderful shot.</td>', 'Good composition.The clouds are really beautiful. Love the angle, this is the level that kids would look up at the sky. Wonderful shot.', '2003-09-02 05:40:38.000000', NULL, 1),
(406950, 35865, 9098, '<td valign="top">Definitely reminds me of going back to school.  This would have been perfect for the repetition challenge, too.  I like the angle you used.</td>', 'Definitely reminds me of going back to school.  This would have been perfect for the repetition challenge, too.  I like the angle you used.', '2003-09-02 10:17:24.000000', NULL, 1),
