(406988, 35886, 5112, '<td valign="top">And the first lesson should be in spelling :))  Good idea!</td>', 'And the first lesson should be in spelling :))  Good idea!', '2003-09-02 11:18:40.000000', NULL, 1),
(406989, 35861, 10871, '<td valign="top">hmm..its great idea to have more negative space in composition.. it keps viewer thinking..good job</td>', 'hmm..its great idea to have more negative space in composition.. it keps viewer thinking..good job', '2003-09-02 11:18:59.000000', NULL, 1),
(406992, 35854, 5112, '<td valign="top">What a clean bus!  I love the cloud reflected in the window.  Nice crop.  Fits the challenge well.  ~9</td>', 'What a clean bus!  I love the cloud reflected in the window.  Nice crop.  Fits the challenge well.  ~9', '2003-09-02 11:20:30.000000', NULL, 1),
(406994, 35571, 5112, '<td valign="top">I love the blurry hand in the front, and the child''s expression!  The picture would be a bit better IMO if the focus were on the child''s eyes. ~7</td>', 'I love the blurry hand in the front, and the child''s expression!  The picture would be a bit better IMO if the focus were on the child''s eyes. ~7', '2003-09-02 11:21:40.000000', NULL, 1),
