(407175, 35730, 11155, '<td valign="top">Very creative.  Would have liked less motion blur.   Funny.</td>', 'Very creative.  Would have liked less motion blur.   Funny.', '2003-09-02 15:09:59.000000', NULL, 1),
(407188, 35929, 5391, '<td valign="top">One of my favorites of the challenge.  I love the colors and high contrast.  Nice composition, too, with the book, the apple and the blackboard.  Nothing about this that doesn''t say "school".  10</td>', 'One of my favorites of the challenge.  I love the colors and high contrast.  Nice composition, too, with the book, the apple and the blackboard.  Nothing about this that doesn''t say "school".  10', '2003-09-02 15:40:19.000000', NULL, 1),
